-- Schema operacional: campos pessoais cifrados e índices cegos HMAC.
PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000;
CREATE TABLE IF NOT EXISTS usuarios(id_usuario INTEGER PRIMARY KEY AUTOINCREMENT, dados BLOB NOT NULL, email_indice TEXT UNIQUE NOT NULL, senha_hash TEXT NOT NULL, perfil TEXT NOT NULL CHECK(perfil IN ('ADMINISTRADOR','OPERADOR')), ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN(0,1)), data_cadastro TEXT DEFAULT CURRENT_TIMESTAMP, data_atualizacao TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clientes(id_cliente INTEGER PRIMARY KEY AUTOINCREMENT, dados BLOB NOT NULL, documento_indice TEXT UNIQUE, ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN(0,1)), versao INTEGER NOT NULL DEFAULT 1, data_cadastro TEXT DEFAULT CURRENT_TIMESTAMP, data_atualizacao TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contatos(id_contato INTEGER PRIMARY KEY AUTOINCREMENT, id_cliente INTEGER NOT NULL REFERENCES clientes ON DELETE RESTRICT, tipo TEXT NOT NULL CHECK(tipo IN('TELEFONE','WHATSAPP','EMAIL','INSTAGRAM','LINKEDIN','FACEBOOK','SITE','OUTRO')), dados BLOB NOT NULL, valor_indice TEXT NOT NULL, principal INTEGER NOT NULL CHECK(principal IN(0,1)), UNIQUE(id_cliente,tipo,valor_indice));
CREATE UNIQUE INDEX IF NOT EXISTS contato_principal ON contatos(id_cliente,tipo) WHERE principal=1;
CREATE TABLE IF NOT EXISTS enderecos(id_endereco INTEGER PRIMARY KEY AUTOINCREMENT, id_cliente INTEGER NOT NULL REFERENCES clientes ON DELETE RESTRICT, dados BLOB NOT NULL, principal INTEGER NOT NULL CHECK(principal IN(0,1)));
CREATE UNIQUE INDEX IF NOT EXISTS endereco_principal ON enderecos(id_cliente) WHERE principal=1;
CREATE TABLE IF NOT EXISTS documentos(id_documento INTEGER PRIMARY KEY AUTOINCREMENT, id_cliente INTEGER NOT NULL REFERENCES clientes ON DELETE RESTRICT, id_usuario_envio INTEGER NOT NULL REFERENCES usuarios ON DELETE RESTRICT, dados BLOB NOT NULL, conteudo BLOB NOT NULL, tamanho_bytes INTEGER NOT NULL, data_envio TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS processos(id_processo INTEGER PRIMARY KEY AUTOINCREMENT, id_cliente INTEGER NOT NULL REFERENCES clientes ON DELETE RESTRICT, numero_indice TEXT UNIQUE NOT NULL, dados BLOB NOT NULL, status TEXT NOT NULL CHECK(status IN('EM_ANALISE','EM_ANDAMENTO','AGUARDANDO_AUDIENCIA','AGUARDANDO_DECISAO','SUSPENSO','EM_RECURSO','ENCERRADO','ARQUIVADO')), ramo TEXT NOT NULL CHECK(ramo IN('CIVEL','FAMILIA','CONSUMIDOR','TRABALHISTA','PREVIDENCIARIO','EMPRESARIAL','TRIBUTARIO','ADMINISTRATIVO','IMOBILIARIO','SUCESSOES','OUTRO')), tipificacao TEXT NOT NULL, situacao TEXT NOT NULL CHECK(situacao IN('ATIVO','ENCERRADO','ARQUIVADO')), data_abertura TEXT NOT NULL, valor_estimado_centavos INTEGER NOT NULL DEFAULT 0 CHECK(valor_estimado_centavos>=0), versao INTEGER NOT NULL DEFAULT 1, data_cadastro TEXT DEFAULT CURRENT_TIMESTAMP, data_atualizacao TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS historico_processos(id_historico INTEGER PRIMARY KEY AUTOINCREMENT, id_processo INTEGER NOT NULL REFERENCES processos ON DELETE CASCADE, id_usuario INTEGER NOT NULL REFERENCES usuarios ON DELETE RESTRICT, dados BLOB NOT NULL, data_hora TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recebimentos(id_recebimento INTEGER PRIMARY KEY AUTOINCREMENT, id_processo INTEGER NOT NULL REFERENCES processos ON DELETE RESTRICT, id_usuario INTEGER NOT NULL REFERENCES usuarios ON DELETE RESTRICT, dados BLOB NOT NULL, valor_centavos INTEGER NOT NULL CHECK(valor_centavos>0), data_recebimento TEXT NOT NULL, data_cadastro TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS arquivos_processos(id_arquivo INTEGER PRIMARY KEY AUTOINCREMENT, id_processo INTEGER NOT NULL REFERENCES processos ON DELETE RESTRICT, id_usuario_envio INTEGER NOT NULL REFERENCES usuarios ON DELETE RESTRICT, categoria TEXT NOT NULL CHECK(categoria IN('FOTO','DOCUMENTO')), dados BLOB NOT NULL, conteudo BLOB NOT NULL, miniatura BLOB, tamanho_bytes INTEGER NOT NULL CHECK(tamanho_bytes>0), data_envio TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS logs_auditoria(id_log INTEGER PRIMARY KEY AUTOINCREMENT, id_usuario INTEGER NOT NULL REFERENCES usuarios ON DELETE RESTRICT, acao TEXT NOT NULL CHECK(acao IN('CADASTRO','ALTERACAO','EXCLUSAO','LEITURA','LOGIN','LOGOUT')), tabela_afetada TEXT NOT NULL, id_registro INTEGER NOT NULL, data_hora TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessoes(id_sessao TEXT PRIMARY KEY, id_usuario INTEGER NOT NULL REFERENCES usuarios ON DELETE CASCADE, refresh_hash TEXT UNIQUE NOT NULL, csrf TEXT NOT NULL, expira INTEGER NOT NULL, criado INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS refresh_tokens_usados(token_hash TEXT PRIMARY KEY, id_sessao TEXT NOT NULL, id_usuario INTEGER NOT NULL, expira INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tentativas(chave TEXT PRIMARY KEY, total INTEGER NOT NULL, expira INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS desafios_mfa(token_hash TEXT PRIMARY KEY, id_usuario INTEGER NOT NULL REFERENCES usuarios ON DELETE CASCADE, codigo_hash TEXT NOT NULL, ip_indice TEXT NOT NULL, senha_indice TEXT NOT NULL, tentativas INTEGER NOT NULL DEFAULT 0 CHECK(tentativas BETWEEN 0 AND 5), proximo_envio INTEGER NOT NULL, expira INTEGER NOT NULL, criado INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS documentos_cliente ON documentos(id_cliente);
CREATE INDEX IF NOT EXISTS documentos_usuario ON documentos(id_usuario_envio);
CREATE INDEX IF NOT EXISTS processos_cliente ON processos(id_cliente);
CREATE INDEX IF NOT EXISTS processos_filtros ON processos(status,ramo,situacao,data_abertura);
CREATE INDEX IF NOT EXISTS processos_atualizacao ON processos(data_atualizacao);
CREATE INDEX IF NOT EXISTS historico_processo_data ON historico_processos(id_processo,data_hora);
CREATE INDEX IF NOT EXISTS recebimentos_processo_data ON recebimentos(id_processo,data_recebimento);
CREATE INDEX IF NOT EXISTS arquivos_processo ON arquivos_processos(id_processo);
CREATE INDEX IF NOT EXISTS enderecos_cliente ON enderecos(id_cliente);
CREATE INDEX IF NOT EXISTS logs_usuario_data ON logs_auditoria(id_usuario,data_hora);
CREATE INDEX IF NOT EXISTS logs_tabela_registro ON logs_auditoria(tabela_afetada,id_registro);
CREATE INDEX IF NOT EXISTS sessoes_usuario ON sessoes(id_usuario);
CREATE INDEX IF NOT EXISTS sessoes_expira ON sessoes(expira);
CREATE INDEX IF NOT EXISTS refresh_tokens_usados_expira ON refresh_tokens_usados(expira);
CREATE INDEX IF NOT EXISTS tentativas_expira ON tentativas(expira);
CREATE INDEX IF NOT EXISTS desafios_mfa_usuario ON desafios_mfa(id_usuario);
CREATE INDEX IF NOT EXISTS desafios_mfa_expira ON desafios_mfa(expira);
